import fs from 'fs';
import readline from 'readline';
import crypto from 'node:crypto';
import { getDb } from './db.mjs';

function hashPassword(password) {
  const salt = 'carpool_salt_2026';
  const hash = crypto.pbkdf2Sync(password, salt, 1000, 32, 'sha256').toString('hex');
  return salt + ':' + hash;
}

const transcriptPath = 'C:\\Users\\argha\\.gemini\\antigravity-ide\\brain\\54fcc0fe-5adb-4708-a6a2-03704b23b4d8\\.system_generated\\logs\\transcript.jsonl';

async function parsePDFs() {
  const fileStream = fs.createReadStream(transcriptPath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  let fullText = '';

  for await (const line of rl) {
    try {
      const parsed = JSON.parse(line);
      if (parsed.type === 'USER_INPUT' && parsed.content && parsed.content.includes('==Start of PDF==')) {
        fullText = parsed.content;
        break;
      }
    } catch (e) {
      // ignore JSON parse errors for lines that might be malformed
    }
  }

  if (!fullText) {
    console.error('Could not find PDF text in transcript.');
    return;
  }

  const pdfBlocks = fullText.split('==Start of PDF==').slice(1).map(block => block.split('==End of PDF==')[0]);
  if (pdfBlocks.length < 2) {
    console.error('Expected at least 2 PDF blocks.');
    return;
  }

  const empPdf = pdfBlocks[0];
  const vehPdf = pdfBlocks[1];

  // Helper to extract lines from all pages of a certain type
  function extractPages(pdfText, startPage, endPage) {
    const lines = [];
    for (let i = startPage; i <= endPage; i++) {
      const pageStart = \`==Start of OCR for page \${i}==\`;
      const pageEnd = \`==End of OCR for page \${i}==\`;
      const pStartIdx = pdfText.indexOf(pageStart);
      const pEndIdx = pdfText.indexOf(pageEnd);
      if (pStartIdx !== -1 && pEndIdx !== -1) {
        let content = pdfText.substring(pStartIdx + pageStart.length, pEndIdx).trim();
        const pageLines = content.split('\\n').map(l => l.trim()).filter(l => l);
        // Remove header on first page
        if (i === startPage) pageLines.shift();
        lines.push(...pageLines);
      }
    }
    return lines;
  }

  // Parse Employees
  // Pages 1-8: Full Name, Corporate Email, Mobile Number, Employee ID
  const empInfoLines = extractPages(empPdf, 1, 8);
  // Pages 9-16: Department, Base Office Hub, Platform Role
  const empRoleLines = extractPages(empPdf, 9, 16);
  // Pages 17-24: Initial Wallet Credit
  const empWalletLines = extractPages(empPdf, 17, 24);

  const employees = [];
  for (let i = 0; i < empInfoLines.length; i++) {
    // Info line example: Aryan Mondal aryan.mondal001@kolkatamobility.example +91 9861052066 EMP-1001
    // Let's match from the back to handle names with multiple words
    const m = empInfoLines[i].match(/(.+?)\\s+([a-zA-Z0-9._-]+@[a-zA-Z0-9.-]+\\.[a-zA-Z]+[a-zA-Z+0-9]*)\\s+(\\+91\\s*\\d{10})\\s+(EMP-\\d+)/);
    if (!m) {
      // Try fallback regex if email broke in OCR
      const m2 = empInfoLines[i].match(/(.+?)\\s+(\\S+@\\S+)\\s+(\\+91\\s*\\d{10})\\s+(EMP-\\d+)/);
      if (!m2) {
          console.warn('Could not parse emp info line:', empInfoLines[i]);
          continue;
      }
      m = m2;
    }

    // Role line example: Engineering Salt Lake Corporate Hub Employee (Carpool Rider/Driver)
    // We can assume Department is first word (or 2 if Human Resources/Customer Support/Data Analytics), then Base Office Hub, then Platform Role.
    // Let's use simple match based on known Hubs:
    // Hubs: Salt Lake Corporate Hub, Rajarhat Corporate Hub, Kolkata Tech Hub (Sector V), New Town Mobility Hub, Park Street Business Hub, Howrah Transit Hub, Esplanade Mobility Hub, Dum Dum Business Hub
    const rLine = empRoleLines[i] || '';
    const hubs = ['Salt Lake Corporate Hub', 'Rajarhat Corporate Hub', 'Kolkata Tech Hub (Sector V)', 'New Town Mobility Hub', 'Park Street Business Hub', 'Howrah Transit Hub', 'Esplanade Mobility Hub', 'Dum Dum Business Hub'];
    let dept = '', hub = '', role = '';

    for (const h of hubs) {
      const idx = rLine.indexOf(h);
      if (idx !== -1) {
        dept = rLine.substring(0, idx).trim();
        hub = h;
        role = rLine.substring(idx + h.length).trim();
        break;
      }
    }

    const wallet = parseFloat(empWalletLines[i]) || 0;

    employees.push({
      name: m[1].trim(),
      email: m[2].replace(/[+ ]/g, '').trim(),
      mobile: m[3].trim(),
      empId: m[4].trim(),
      dept,
      loc: hub,
      role: 'employee',
      wallet,
      platformRole: role
    });
  }

  // Parse Vehicles
  // Pages 1-7: Vehicle Model, WB Plate Number, Assigned Driver / Owner, Seating Capacity
  const vehInfoLines = extractPages(vehPdf, 1, 7);
  // Pages 8-14: Vehicle Type, Fuel Type, Color
  const vehSpecLines = extractPages(vehPdf, 8, 14);

  const vehicles = [];
  for (let i = 0; i < vehInfoLines.length; i++) {
    // Info line: Hyundai i20 WB24L5293 Sanjana Chatterjee 5 Seats
    const match = vehInfoLines[i].match(/(.+?)\\s+(WB\\d+[A-Z]+\\d+)\\s+(.+?)\\s+(\\d+)\\s+Seats/i);
    if (!match) {
      console.warn('Could not parse veh info line:', vehInfoLines[i]);
      continue;
    }

    const sLine = vehSpecLines[i] || '';
    // Spec line: Hatchback Petrol Midnight Black
    // Fuel types: Petrol, Diesel, Electric, Hybrid, CNG
    const fuels = ['Petrol', 'Diesel', 'Electric', 'Hybrid', 'CNG'];
    let fuel = '', vType = '', color = '';
    for (const f of fuels) {
      const idx = sLine.indexOf(f);
      if (idx !== -1) {
        vType = sLine.substring(0, idx).trim();
        fuel = f;
        color = sLine.substring(idx + f.length).trim();
        break;
      }
    }

    // For EVs the fuel type in DB is often 'Electric (EV)'
    if (fuel === 'Electric') fuel = 'Electric (EV)';

    vehicles.push({
      model: match[1].trim(),
      plate: match[2].trim(),
      ownerName: match[3].trim(),
      capacity: parseInt(match[4], 10),
      vType,
      fuel,
      color
    });
  }

  console.log(\`Parsed \${employees.length} employees and \${vehicles.length} vehicles.\`);

  // Insert into DB
  const db = getDb();
  const defaultPasswordHash = hashPassword('password123');

  const empStmt = db.prepare('INSERT INTO employees (id, name, email, password_hash, role, wallet_balance, access_status, department, mobile, employee_id, manager, office_location, avatar, rating, total_trips, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');

  // Create a map to find employee id by name for vehicles
  const nameToId = {};

  // Clean up any previously added dummy data if needed? The user said "insert and add all the new data in vehicle and new employee/staff".
  // Let's remove the 350 and 300 we added previously to avoid bloat, since they were random.
  console.log('Removing previously added temporary dummy employees/vehicles...');
  db.prepare("DELETE FROM rides WHERE vehicle_id LIKE 'veh-new-%'").run();
  db.prepare("DELETE FROM vehicles WHERE id LIKE 'veh-new-%'").run();
  db.prepare("DELETE FROM employees WHERE id LIKE 'emp-new-%'").run();

  let empCount = 0;
  for (let i = 0; i < employees.length; i++) {
    const emp = employees[i];
    const id = 'emp-real-' + String(i + 1).padStart(4, '0');
    nameToId[emp.name] = id;

    try {
      empStmt.run(
        id,
        emp.name,
        emp.email,
        defaultPasswordHash,
        emp.role,
        emp.wallet,
        'granted',
        emp.dept,
        emp.mobile,
        emp.empId,
        'Admin User',
        emp.loc,
        \`https://ui-avatars.com/api/?name=\${encodeURIComponent(emp.name)}&background=random\`,
        4.9,
        0,
        new Date().toISOString()
      );
      empCount++;
    } catch(e) {
      console.error('Error inserting employee:', emp.name, e.message);
    }
  }

  const vehStmt = db.prepare('INSERT INTO vehicles (id, owner_id, model, registration_plate, capacity, fuel_type, color, driver_name, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');

  let vehCount = 0;
  for (let i = 0; i < vehicles.length; i++) {
    const veh = vehicles[i];
    const vId = 'veh-real-' + String(i + 1).padStart(4, '0');
    const ownerId = nameToId[veh.ownerName] || 'emp-001'; // fallback to Raj Patel if not found

    try {
      vehStmt.run(
        vId,
        ownerId,
        veh.model,
        veh.plate,
        veh.capacity,
        veh.fuel,
        veh.color,
        veh.ownerName,
        'active',
        new Date().toISOString()
      );
      vehCount++;
    } catch(e) {
      console.error('Error inserting vehicle:', veh.plate, e.message);
    }
  }

  console.log(\`Successfully inserted \${empCount} employees and \${vehCount} vehicles.\`);
}

parsePDFs().catch(console.error);
